import{_ as o,l as i,o as e,c as s,v as r,p as l,x as n,d,i as E,S as p}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"金本位与大萧条","description":"","frontmatter":{"title":"金本位与大萧条","date":"2026-09-10T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/gold-standard-depression.md","filePath":"econ/gold-standard-depression.md","lastUpdated":1789023840000}'),B={name:"econ/gold-standard-depression.md"};function h(c,a,A,m,_,f){const t=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="金本位与大萧条" tabindex="-1">金本位与大萧条 <a class="header-anchor" href="#金本位与大萧条" aria-label="Permalink to &quot;金本位与大萧条&quot;">​</a></h1><div class="epigraph"><p>金本位把汇率钉死、把货币政策绑在黄金，于是一国的紧缩经储备流失变成多国的通缩。早脱离金平价的经济更早再通胀——制度比编年更能解释为何萧条是全球的。</p><footer>—— Friedman and Schwartz, A Monetary History of the United States, 1963；Eichengreen, Golden Fetters, 1992；Bernanke, Essays on the Great Depression, 2000</footer></div><p><a href="/econ/local-fiscal-transfers">上一课</a>收束公共财政。本课是<strong>经济史</strong>对照课的第一课；后课默认已经读完：危机用机制对照，不背年份表。缺口是：1929 年的美国股价与银行恐慌，如何变成十年的全球萧条。Friedman–Schwartz 钉住美联储让货币崩溃；Bernanke 补上金融加速器；Eichengreen 把金本位写成国际传导的枷锁。三句话要叠在一起，不能只留一句「股市崩了」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>钉住黄金：外部流失必须紧缩国内信用，否则平价不保。1920 年代末各国以扭曲的平价回到金本位，储备集中，规则不对称——盈余国不必膨胀，赤字国必须收缩。1929 年后美国信用收缩、银行倒闭，黄金与资本流动把通缩输出。名义工资与债务粘住，实际负担上升，破产与挤兑互相加强。缺口不是列出哪一年谁破产，而是：<strong>在浮动下可以各自再通胀的政策，在金本位下是「不负责任」</strong>；于是对称紧缩。英国 1931、美国 1933 脱离金本位后，工业与价格更早拐头——这是截面对照，不是故事高潮。</p><h3 id="大萧条不是「股市跌了所以十年」" tabindex="-1">大萧条不是「股市跌了所以十年」 <a class="header-anchor" href="#大萧条不是「股市跌了所以十年」" aria-label="Permalink to &quot;大萧条不是「股市跌了所以十年」&quot;">​</a></h3><p>股价是资产价格；十年萧条要货币、银行、债务通缩与国际制度。只讲 1929 年 10 月，会把因果收成市场情绪，并解释不了为何脱离金本位的时点预测复苏时点。银行倒闭摧毁的是信用中介，Bernanke 的加速器把这层从货币总量里拆出来：同样的 \\(M\\) 下降，金融摩擦让 \\(Y\\) 掉得更深。</p><p><span class="marginnote">Bernanke 后来对 Friedman–Schwartz 的致敬，影响了 2008 年对银行与流动性的反应。史课对照的是机制是否可迁移，不是把 1930 年代当剧本重演。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三层对照。(1) 货币：Friedman–Schwartz 的 \\(M\\) 崩溃与银行恐慌。(2) 金融加速器：净值下降 → 抵押与惜贷 → 投资消费再下降。(3) 金本位：固定汇率加黄金约束 = 输出通缩、禁止单独再通胀。政策实验是「何时脱离」：早脱离者更早 reflate。财政在金本位下也被「保卫平价」绑住，乘数课的工具集当时是空的。</p>',10)),(e(),l(p,null,{default:n(()=>[E(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20PF%5B%22%E5%85%AC%E5%85%B1%E8%B4%A2%E6%94%BF%E6%94%B6%E6%9D%9F%22%5D%20--%3E%20GS%5B%22%E9%87%91%E6%9C%AC%E4%BD%8D%E7%BA%A6%E6%9D%9F%22%5D%0A%20%20GS%20--%3E%20DEF%5B%22%E5%82%A8%E5%A4%87%E6%B5%81%E5%A4%B1%E5%BF%85%E9%A1%BB%E7%B4%A7%E7%BC%A9%22%5D%0A%20%20DEF%20--%3E%20ACC%5B%22%E5%80%BA%E5%8A%A1%E9%80%9A%E7%BC%A9%E4%B8%8E%E9%93%B6%E8%A1%8C%E5%8A%A0%E9%80%9F%E5%99%A8%22%5D%0A%20%20ACC%20--%3E%20EXIT%5B%22%E8%84%B1%E7%A6%BB%E9%87%91%E5%B9%B3%E4%BB%B7%E6%89%8D%E8%83%BD%E5%86%8D%E9%80%9A%E8%83%80%22%5D%0A%20%20EXIT%20--%3E%20BW%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%3A%20%E5%B8%83%E9%9B%B7%E9%A1%BF%E6%A3%AE%E6%9E%97%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>不要用战争赔款年表替代黄金约束；赔款是冲击，金本位是传导。银行倒闭的截面：更多依赖批发与房地产抵押的体系，加速器更陡——Bernanke 用各国银行结构解释深度差异，与「都是金本位」不矛盾：枷锁管广度，加速器管深度。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是开放经济的三角在金本位下的极限：资本流动 + 固定平价 ⇒ 没有独立 \\(M\\)。通缩提高实际利率与实际债务，净值蒸发，银行挤兑——国内加速器与国际枷锁相乘。浮动后，\\(M\\) 可以扩张，价格预期扭转，加速器反号。这与后课布雷顿森林的「金汇兑」是同一金约束的不同松紧：那里美元居中，这里多国直接钉金。</p><p>与地方财政对照：地方不能印金（或印储备货币）；金本位下的主权也近似不能。层级不同，约束形状同族。金汇兑（部分储备）比纯金本位松一截，但仍把外部流失写成国内紧缩。后课布雷顿是把这一松一截制度化到美元身上。</p><p><span class="marginnote">Eichengreen, <em>Golden Fetters</em>：金本位不仅传导冲击，还通过信誉政治阻止国内稳定政策。早脱钩是政策选择，不是自然康复。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写交易策略，不进限价簿，不把每场银行倒闭列成编年。下一课：战后用美元–黄金重建固定汇率，松的是直接金本位，紧的是美元兑换承诺——Triffin 会把它拆掉。后课默认：大萧条的国际部分用金本位枷锁读；国内部分用货币崩溃加金融加速器读。不要只留股市。金平价若一开始就定错，枷锁在繁荣期已经在积压力，危机只是把约束写进价格。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>本课是经济史第一课；后课用制度对照，不堆编年。</li><li>金本位迫使对称紧缩，把一国通缩输出为全球萧条。</li><li>早脱离金平价者更早再通胀，是机制证据。</li><li>货币崩溃与银行加速器解释深度，金本位解释广度。</li><li>出处：Friedman and Schwartz 1963；Eichengreen 1992；Bernanke 2000。</li></ul>',9))])}const S=o(B,[["render",h]]);export{D as __pageData,S as default};
